// ── BEFORE: monolithic request handler ────────────────────────
// All concerns tangled together — impossible to reorder or test in isolation
app.post('/api/orders', (req, res) => {
  // Logging
  console.log(`[${new Date().toISOString()}] POST /api/orders`);

  // Auth check
  if (!req.headers['x-api-key']) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Rate limit check
  if (rateLimitExceeded(req.ip)) {
    return res.status(429).json({ error: 'Too Many Requests' });
  }

  // Actual business logic
  const order = createOrder(req.body);
  res.json({ orderId: order.id });
});

// ── AFTER: Chain of Responsibility — each concern is one link ─
function logger(req, res, next) {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // always delegates — pure observer
}

function requireApiKey(req, res, next) {
  if (!req.headers['x-api-key']) {
    return res.status(401).json({ error: 'Unauthorized' }); // chain stops
  }
  next();
}

function rateLimit(req, res, next) {
  if (rateLimitExceeded(req.ip)) {
    return res.status(429).json({ error: 'Too Many Requests' }); // chain stops
  }
  next();
}

// Assemble the chain — order is explicit and readable
app.use(logger);
app.use(requireApiKey);
app.use(rateLimit);

app.post('/api/orders', (req, res) => {
  const order = createOrder(req.body); // pure business logic — no auth/log noise
  res.json({ orderId: order.id });
});

// ── Koa onion model: Decorator on top of Chain of Responsibility
const Koa = require('koa');
const compose = require('koa-compose');
const koa = new Koa();

async function timing(ctx, next) {
  const start = Date.now();
  await next();                          // run everything inside
  const ms = Date.now() - start;
  ctx.set('X-Response-Time', `${ms}ms`); // runs AFTER inner handlers
}

async function respond(ctx, next) {
  await next();
  ctx.body = ctx.body || 'Hello';
}

koa.use(timing);
koa.use(respond);
// timing wraps respond: start → respond runs → timing records duration

// ── Minimal Redux implementation exposing all three patterns ──
function createStore(reducer, initialState) {
  let state = initialState;
  const listeners = [];              // Observer: subscriber list

  return {
    // Singleton contract: one object, one state
    getState: () => state,

    // Command executor: action is a serialisable Command object
    dispatch(action) {
      if (typeof action !== 'object' || !action.type) {
        throw new Error('Actions must be plain objects with a type property');
      }
      state = reducer(state, action); // execute the command
      listeners.forEach(fn => fn());  // notify all Observers
    },

    // Observer: register a subscriber
    subscribe(listener) {
      listeners.push(listener);
      return () => {                  // returns unsubscribe function
        const idx = listeners.indexOf(listener);
        listeners.splice(idx, 1);
      };
    },
  };
}

// Reducer: pure function — given state + command, returns new state
function counterReducer(state = { count: 0 }, action) {
  switch (action.type) {
    case 'INCREMENT': return { count: state.count + (action.by ?? 1) };
    case 'DECREMENT': return { count: state.count - (action.by ?? 1) };
    case 'RESET':     return { count: 0 };
    default:          return state;
  }
}

// Singleton usage
const store = createStore(counterReducer);

// Observer: register listeners
const unsubA = store.subscribe(() =>
  console.log('Component A sees:', store.getState())
);
const unsubB = store.subscribe(() =>
  console.log('Component B sees:', store.getState())
);

// Command: dispatch serialisable action objects
store.dispatch({ type: 'INCREMENT', by: 5 });
// Component A sees: { count: 5 }
// Component B sees: { count: 5 }

store.dispatch({ type: 'INCREMENT', by: 3 });
// Component A sees: { count: 8 }
// Component B sees: { count: 8 }

// Commands are data — you can log, replay, diff them
const actionLog = [];
const loggingStore = createStore(counterReducer);
loggingStore.subscribe(() => {});
const originalDispatch = loggingStore.dispatch.bind(loggingStore);
loggingStore.dispatch = (action) => {
  actionLog.push({ ...action, timestamp: Date.now() }); // log the Command
  originalDispatch(action);
};
loggingStore.dispatch({ type: 'INCREMENT', by: 1 });
loggingStore.dispatch({ type: 'INCREMENT', by: 2 });
console.log('Replay log:', actionLog);
// [{type:'INCREMENT',by:1,timestamp:...}, {type:'INCREMENT',by:2,timestamp:...}]

// Unsubscribe Observer
unsubA();
store.dispatch({ type: 'RESET' });
// Only Component B is notified now

