// ── BEFORE: string concatenation query building — fragile and unsafe ──
function getActiveUsers(minOrders, limit, offset) {
  let sql = 'SELECT users.* FROM users';
  sql += ' LEFT JOIN orders ON orders.user_id = users.id';
  if (minOrders) {
    sql += ` WHERE users.active = true AND COUNT(orders.id) > ${minOrders}`; // injection risk!
  } else {
    sql += ' WHERE users.active = true';
  }
  if (limit) sql += ` LIMIT ${limit}`;
  if (offset) sql += ` OFFSET ${offset}`;
  return db.query(sql); // partially assembled queries are a common source of bugs
}

// ── AFTER: Builder pattern — fluent, safe, composable ──────────
class QueryBuilder {
  constructor(table) {
    this._table = table;
    this._conditions = [];
    this._params = {};
    this._joins = [];
    this._orderBy = null;
    this._limit = null;
    this._offset = null;
    this._paramCount = 0;
  }

  // Each method returns this — fluent interface
  leftJoin(table, on) {
    this._joins.push(`LEFT JOIN ${table} ON ${on}`);
    return this;
  }

  where(condition, params = {}) {
    // Parameterise to prevent SQL injection
    let safe = condition;
    for (const [key, value] of Object.entries(params)) {
      const placeholder = `$${++this._paramCount}`;
      safe = safe.replace(`:${key}`, placeholder);
      this._params[placeholder] = value;
    }
    this._conditions.push(safe);
    return this;
  }

  orderBy(col, dir = 'ASC') {
    this._orderBy = `ORDER BY ${col} ${dir}`;
    return this;
  }

  take(n)   { this._limit = n;  return this; }
  skip(n)   { this._offset = n; return this; }

  // build() converts accumulated state into the final SQL — Builder's terminal step
  build() {
    const joins = this._joins.join(' ');
    const where = this._conditions.length
      ? `WHERE ${this._conditions.join(' AND ')}`
      : '';
    const order  = this._orderBy ?? '';
    const limit  = this._limit  != null ? `LIMIT ${this._limit}`  : '';
    const offset = this._offset != null ? `OFFSET ${this._offset}` : '';
    const sql = `SELECT ${this._table}.* FROM ${this._table} ${joins} ${where} ${order} ${limit} ${offset}`
      .replace(/\s+/g, ' ').trim();
    return { sql, params: this._params };
  }

  // execute() is build() + run — the director step
  execute() {
    const { sql, params } = this.build();
    return db.query(sql, Object.values(params));
  }
}

// Usage: accumulate conditions across application layers
const qb = new QueryBuilder('users');

// Base query built in service layer
qb.leftJoin('orders', 'orders.user_id = users.id')
  .where('users.active = :active', { active: true });

// Pagination added by controller layer
qb.take(10).skip(20);

// Conditional filter added by business logic
if (minOrders > 0) {
  qb.where('users.order_count > :min', { min: minOrders });
}

const { sql, params } = qb.build();
console.log(sql);
// SELECT users.* FROM users LEFT JOIN orders ON orders.user_id = users.id
// WHERE users.active = $1 AND users.order_count > $2
// LIMIT 10 OFFSET 20
console.log(params); // { '$1': true, '$2': 0 }
